import { css } from '@emotion/css';
import cx from 'clsx';
import { useState } from 'react';

import { type GrafanaTheme2 } from '@grafana/data';
import { t } from '@grafana/i18n';
import { logError } from '@grafana/runtime';
import { Button, copyTextToClipboard, type IconName, Tooltip, useStyles2 } from '@grafana/ui';

const getStyles = (theme: GrafanaTheme2) => ({
  CopyIcon: css({
    backgroundColor: 'transparent',
    border: 'none',
    color: 'inherit',
    overflow: 'hidden',
    '&:focus': {
      backgroundColor: theme.colors.action.focus,
      color: 'inherit',
    },
  }),
});

type PropsType = {
  className?: string;
  copyText: string;
  icon?: IconName;
  tooltipTitle: string;
};

export default function CopyIcon({ className, copyText, icon = 'copy', tooltipTitle }: PropsType) {
  const styles = useStyles2(getStyles);

  const [hasCopied, setHasCopied] = useState(false);

  const handleClick = async () => {
    try {
      await copyTextToClipboard(copyText);
      setHasCopied(true);
    } catch (error) {
      logError(error instanceof Error ? error : new Error(String(error)));
    }
  };

  return (
    <Tooltip content={hasCopied ? t('explore.trace-view.tooltip-copy-icon', 'Copied') : tooltipTitle}>
      <Button
        aria-label={t('explore.trace-view.aria-label-copy', 'Copy to clipboard')}
        className={cx(styles.CopyIcon, className)}
        type="button"
        icon={icon}
        fill="text"
        size="sm"
        onClick={handleClick}
      />
    </Tooltip>
  );
}
